import base64
import random
from typing import Tuple

# This generator emits a variety of valid private key encodings (PEM or DER) for wolfSSL_*_use_PrivateKey_file.
# It creates structurally valid ASN.1 for:
#  - PKCS#1 RSA PRIVATE KEY
#  - PKCS#8 PRIVATE KEY (RSA or EC)
#  - SEC1 EC PRIVATE KEY (named curve)
# Keys are minimal but syntactically valid; values are not cryptographically strong, which is acceptable for parser tests.
# To maximize uniqueness, several fields vary with the RNG including integer sizes and curve selection.

# ---------------- ASN.1 helpers ----------------

def der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    s = []
    v = length
    while v > 0:
        s.append(v & 0xFF)
        v >>= 8
    s = bytes(reversed(s))
    return bytes([0x80 | len(s)]) + s


def der_integer_bytes(n: int) -> bytes:
    if n == 0:
        return b"\x00"
    bts = bytearray()
    v = n
    while v > 0:
        bts.append(v & 0xFF)
        v >>= 8
    bts = bytes(reversed(bts))
    if bts[0] & 0x80:
        bts = b"\x00" + bts
    return bts


def der_integer(n: int) -> bytes:
    content = der_integer_bytes(n)
    return b"\x02" + der_len(len(content)) + content


def der_integer_from_bytes(b: bytes) -> bytes:
    # ensure positive
    if len(b) == 0:
        b = b"\x00"
    elif b[0] & 0x80:
        b = b"\x00" + b
    return b"\x02" + der_len(len(b)) + b


def der_octet_string(b: bytes) -> bytes:
    return b"\x04" + der_len(len(b)) + b


def der_null() -> bytes:
    return b"\x05\x00"


def der_object_identifier(oid: Tuple[int, ...]) -> bytes:
    if len(oid) < 2:
        raise ValueError("OID must have at least 2 arcs")
    first = 40 * oid[0] + oid[1]
    body = [first]
    for arc in oid[2:]:
        stack = []
        if arc == 0:
            stack = [0]
        else:
            while arc > 0:
                stack.append(0x80 | (arc & 0x7F))
                arc >>= 7
            stack[0] &= 0x7F
            stack = list(reversed(stack))
        body.extend(stack)
    content = bytes(body)
    return b"\x06" + der_len(len(content)) + content


def der_sequence(content: bytes) -> bytes:
    return b"\x30" + der_len(len(content)) + content


def der_bit_string(bits: bytes, unused_bits: int = 0) -> bytes:
    return b"\x03" + der_len(len(bits) + 1) + bytes([unused_bits]) + bits


def der_context_explicit(tag: int, inner: bytes) -> bytes:
    # [tag] EXPLICIT inner
    tag_byte = 0xA0 | (tag & 0x1F)
    return bytes([tag_byte]) + der_len(len(inner)) + inner


def pem_wrap(label: str, der: bytes) -> bytes:
    b64 = base64.b64encode(der).decode('ascii')
    lines = [b64[i:i+64] for i in range(0, len(b64), 64)]
    pem = f"-----BEGIN {label}-----\n" + "\n".join(lines) + f"\n-----END {label}-----\n"
    return pem.encode('ascii')

# ---------------- Key builders ----------------

RSA_E_OIDS = {
    'rsaEncryption': (1, 2, 840, 113549, 1, 1, 1),
}

EC_CURVE_OIDS = {
    'P-256': (1, 2, 840, 10045, 3, 1, 7),
    'P-384': (1, 3, 132, 0, 34),
    'P-521': (1, 3, 132, 0, 35),
}


def rand_bigint(rnd: random.Random, min_bytes: int, max_bytes: int) -> int:
    nbytes = rnd.randint(min_bytes, max_bytes)
    if nbytes <= 0:
        return 0
    b = bytearray(rnd.getrandbits(8) for _ in range(nbytes))
    # ensure non-zero and positive, and not trivially tiny
    if all(v == 0 for v in b):
        b[-1] = 1
    b[0] |= 0x01
    v = 0
    for x in b:
        v = (v << 8) | x
    return v


def build_rsa_pkcs1(rnd: random.Random) -> bytes:
    # RSAPrivateKey ::= SEQUENCE {version, n, e, d, p, q, dP, dQ, qInv}
    version = der_integer(0)
    # Provide varying sizes to create unique encodings; not necessarily consistent math-wise (parsing focuses on structure)
    n = der_integer(rand_bigint(rnd, 16, 64))
    e_val = rnd.choice([3, 17, 65537])
    e = der_integer(e_val)
    d = der_integer(rand_bigint(rnd, 16, 64))
    p = der_integer(rand_bigint(rnd, 8, 32))
    q = der_integer(rand_bigint(rnd, 8, 32))
    dP = der_integer(rand_bigint(rnd, 8, 32))
    dQ = der_integer(rand_bigint(rnd, 8, 32))
    qInv = der_integer(rand_bigint(rnd, 8, 32))
    return der_sequence(version + n + e + d + p + q + dP + dQ + qInv)


def build_pkcs8_private_key_info(alg_oid: Tuple[int, ...], alg_params: bytes, key_der: bytes) -> bytes:
    version = der_integer(0)
    algid = der_sequence(der_object_identifier(alg_oid) + (alg_params if alg_params is not None else der_null()))
    priv = der_octet_string(key_der)
    return der_sequence(version + algid + priv)


def build_ec_sec1(rnd: random.Random, curve: str) -> bytes:
    version = der_integer(1)
    sizes = {'P-256': 32, 'P-384': 48, 'P-521': 66}
    sz = sizes[curve]
    # Private key with random but non-zero leading byte to vary encodings
    sk = bytearray(rnd.getrandbits(8) for _ in range(sz))
    if all(v == 0 for v in sk):
        sk[-1] = 1
    if sk[0] == 0:
        sk[0] = 1
    priv = der_octet_string(bytes(sk))
    params = der_context_explicit(0, der_object_identifier(EC_CURVE_OIDS[curve]))
    # omit publicKey for brevity
    return der_sequence(version + priv + params)


def build_pkcs8_ec(rnd: random.Random) -> bytes:
    curve = rnd.choice(list(EC_CURVE_OIDS.keys()))
    # AlgorithmIdentifier: id-ecPublicKey (1.2.840.10045.2.1) with namedCurve OID in parameters
    alg_oid = (1, 2, 840, 10045, 2, 1)
    alg_params = der_object_identifier(EC_CURVE_OIDS[curve])
    sec1 = build_ec_sec1(rnd, curve)
    return build_pkcs8_private_key_info(alg_oid, alg_params, sec1)

# ---------------- Top-level selection ----------------


def build_der_and_label(rnd: random.Random) -> Tuple[bytes, str]:
    # Weighted to diversify encodings
    choice = rnd.choices(
        population=['RSA_PKCS1', 'PKCS8_RSA', 'EC_SEC1', 'PKCS8_EC'],
        weights=[30, 25, 25, 20],
        k=1,
    )[0]
    if choice == 'RSA_PKCS1':
        return build_rsa_pkcs1(rnd), 'RSA PRIVATE KEY'
    if choice == 'PKCS8_RSA':
        rsa = build_rsa_pkcs1(rnd)
        return build_pkcs8_private_key_info(RSA_E_OIDS['rsaEncryption'], der_null(), rsa), 'PRIVATE KEY'
    if choice == 'EC_SEC1':
        curve = rnd.choice(list(EC_CURVE_OIDS.keys()))
        return build_ec_sec1(rnd, curve), 'EC PRIVATE KEY'
    # PKCS#8 EC
    return build_pkcs8_ec(rnd), 'PRIVATE KEY'


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    der, label = build_der_and_label(rnd)

    # Randomly decide DER vs PEM to match fuzzer's format selection variability
    as_pem = rnd.random() < 0.7  # bias to PEM
    if as_pem:
        return pem_wrap(label, der)
    else:
        # DER output
        return der[:4096]

import random
import struct
from typing import List

# Generator for a DER-encoded bundle of one or more self-signed CA certificates
# tailored for wolfSSL_CTX_load_verify_locations* fuzzers which call
# FUZZ_PARAM_FILENAME() to obtain a path to a buffer containing CA certs.
#
# We construct minimal but valid X.509 v3 CA certificates in ASN.1 DER.
# Each cert is self-signed (issuer == subject), has BasicConstraints CA:TRUE
# and a minimal SubjectPublicKeyInfo (fake algorithm OID but structurally valid).
# While cryptographically meaningless (no valid signature), parsers commonly
# accept structure enough to exercise loading paths when signature verification
# is deferred or disabled for trust loading.
#
# The file format used is a simple concatenation of DER X.509 certs, which
# is commonly supported as a CA bundle in DER by wolfSSL.

# ASN.1 helpers

def asn1_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    s = []
    while length > 0:
        s.append(length & 0xFF)
        length >>= 8
    return bytes([0x80 | len(s)]) + bytes(reversed(s))

def asn1_tlv(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + asn1_len(len(content)) + content

def asn1_seq(content: bytes) -> bytes:
    return asn1_tlv(0x30, content)

def asn1_set(content: bytes) -> bytes:
    return asn1_tlv(0x31, content)

def asn1_int(n: int) -> bytes:
    # Encode as positive INTEGER
    if n == 0:
        enc = b"\x00"
    else:
        s = bytearray()
        while n > 0:
            s.insert(0, n & 0xFF)
            n >>= 8
        if s[0] & 0x80:
            s.insert(0, 0x00)
        enc = bytes(s)
    return asn1_tlv(0x02, enc)

def asn1_octet_string(b: bytes) -> bytes:
    return asn1_tlv(0x04, b)

def asn1_bit_string(b: bytes, unused_bits: int = 0) -> bytes:
    return asn1_tlv(0x03, bytes([unused_bits]) + b)

def asn1_oid_from_arcs(arcs: List[int]) -> bytes:
    if len(arcs) < 2:
        raise ValueError("OID must have at least two arcs")
    first = 40 * arcs[0] + arcs[1]
    body = [first]
    for a in arcs[2:]:
        # base-128 varint
        stack = []
        if a == 0:
            stack = [0]
        else:
            while a > 0:
                stack.append(0x80 | (a & 0x7F))
                a >>= 7
            stack[0] &= 0x7F  # last byte no continuation
            stack = list(reversed(stack))
        body.extend(stack)
    return asn1_tlv(0x06, bytes(body))

def asn1_null() -> bytes:
    return asn1_tlv(0x05, b"")

def asn1_boolean(val: bool) -> bytes:
    return asn1_tlv(0x01, b"\xff" if val else b"\x00")

def asn1_utctime(year: int, mon: int, day: int, hour: int, minute: int, second: int) -> bytes:
    # UTCTime: YYMMDDHHMMSSZ with year 00-99 -> 1950-2049
    yy = year % 100
    s = f"{yy:02d}{mon:02d}{day:02d}{hour:02d}{minute:02d}{second:02d}Z".encode()
    return asn1_tlv(0x17, s)

def name_common_name(cn: str) -> bytes:
    # Name ::= SEQUENCE of RDNSequence; RDN ::= SET OF AttributeTypeAndValue
    # CN OID = 2.5.4.3, PrintableString
    cn_oid = asn1_oid_from_arcs([2,5,4,3])
    val = asn1_tlv(0x13, cn.encode('ascii', 'ignore')[:64] or b"CA")
    atv = asn1_seq(cn_oid + val)
    rdn = asn1_set(atv)
    return asn1_seq(rdn)

def alg_id_sha256_with_rsa() -> bytes:
    # 1.2.840.113549.1.1.11
    return asn1_seq(asn1_oid_from_arcs([1,2,840,113549,1,1,11]) + asn1_null())

def alg_id_rsa_encryption() -> bytes:
    # 1.2.840.113549.1.1.1
    return asn1_seq(asn1_oid_from_arcs([1,2,840,113549,1,1,1]) + asn1_null())

def minimal_rsa_public_key(mod_bytes: bytes, exp: int = 65537) -> bytes:
    # RSAPublicKey ::= SEQUENCE { modulus INTEGER, publicExponent INTEGER }
    return asn1_seq(asn1_int(int.from_bytes(mod_bytes, 'big')) + asn1_int(exp))

def spki_rsa(mod_bytes: bytes) -> bytes:
    spk = minimal_rsa_public_key(mod_bytes)
    return asn1_seq(alg_id_rsa_encryption() + asn1_bit_string(spk))

def ext_basic_constraints_ca_true(pathlen: int | None) -> bytes:
    # id-ce-basicConstraints = 2.5.29.19, value is SEQUENCE { cA BOOLEAN DEFAULT FALSE, pathLenConstraint INTEGER OPTIONAL }
    seq = asn1_seq(asn1_boolean(True) + (asn1_int(pathlen) if pathlen is not None else b""))
    ext = asn1_seq(
        asn1_oid_from_arcs([2,5,29,19]) +
        asn1_boolean(True) +  # critical
        asn1_octet_string(seq)
    )
    return ext

def ext_key_usage_ca() -> bytes:
    # id-ce-keyUsage = 2.5.29.15, BIT STRING with keyCertSign(5), cRLSign(6)
    bits = 0
    bits |= (1 << (7-5))  # bit index from MSB of first byte (positions 0..7)
    bits |= (1 << (7-6))
    bs = bytes([bits])  # only first 8 bits used; unused bits = 0
    ext = asn1_seq(
        asn1_oid_from_arcs([2,5,29,15]) +
        asn1_boolean(True) +
        asn1_octet_string(asn1_bit_string(bs))
    )
    return ext

def ext_subject_key_id(keyid: bytes) -> bytes:
    # 2.5.29.14
    return asn1_seq(
        asn1_oid_from_arcs([2,5,29,14]) +
        asn1_octet_string(asn1_octet_string(keyid))
    )

def ext_authority_key_id(keyid: bytes) -> bytes:
    # 2.5.29.35, AuthorityKeyIdentifier ::= SEQUENCE { keyIdentifier [0] IMPLICIT OCTET STRING OPTIONAL, ... }
    aki_val = asn1_tlv(0x30, asn1_tlv(0x80, keyid))
    return asn1_seq(
        asn1_oid_from_arcs([2,5,29,35]) +
        asn1_octet_string(aki_val)
    )

def v3_extensions(exts: List[bytes]) -> bytes:
    extseq = asn1_seq(b"".join(exts))
    # [3] EXPLICIT Extensions
    return asn1_tlv(0xA3, extseq)

def tbs_certificate(serial: int, not_before, not_after, subject_cn: str, spki: bytes, is_v3: bool, keyid: bytes) -> bytes:
    # version v3 -> [0] EXPLICIT INTEGER 2
    version = asn1_tlv(0xA0, asn1_int(2)) if is_v3 else b""
    sig = alg_id_sha256_with_rsa()
    issuer = name_common_name(subject_cn)
    subject = issuer
    validity = asn1_seq(
        asn1_utctime(*not_before) +
        asn1_utctime(*not_after)
    )
    exts = v3_extensions([
        ext_basic_constraints_ca_true(pathlen=1),
        ext_key_usage_ca(),
        ext_subject_key_id(keyid),
        ext_authority_key_id(keyid),
    ]) if is_v3 else b""
    tbs = asn1_seq(
        version +
        asn1_int(serial) +
        sig +
        issuer +
        validity +
        subject +
        spki +
        exts
    )
    return tbs

def make_self_signed_ca(random_gen: random.Random, cn: str) -> bytes:
    # Create minimal RSA modulus bytes (fake but positive, 128 bytes)
    mod = bytearray(128)
    for i in range(128):
        mod[i] = random_gen.randrange(1, 256)
    mod[0] |= 0x01  # ensure non-zero first byte; avoid leading sign-bit issues handled by INTEGER encoder
    spki = spki_rsa(bytes(mod))

    # key identifier = SHA-1 like 20 random bytes for linking SKID/AKID
    keyid = bytes(random_gen.getrandbits(8) for _ in range(20))

    # Validity: a broad window around current time using UTCTime within 1950-2049
    # Use fixed plausible dates to avoid local time dependencies
    not_before = (23, 1, 1, 0, 0, 0)  # 2023-01-01Z
    not_after = (49, 12, 31, 23, 59, 59)  # 2049-12-31Z

    serial = random_gen.randrange(1, 1 << 31)
    tbs = tbs_certificate(serial, not_before, not_after, cn, spki, True, keyid)

    # signatureAlgorithm
    sigalg = alg_id_sha256_with_rsa()

    # signatureValue: bit string with dummy bytes
    sig_bytes = bytes(random_gen.getrandbits(8) for _ in range(64))
    sig = asn1_bit_string(sig_bytes)

    cert = asn1_seq(tbs + sigalg + sig)
    return cert


def build_der_bundle(rnd: random.Random, count: int) -> bytes:
    certs = []
    for i in range(count):
        cn = f"Fuzz Test CA {i+1}"
        certs.append(make_self_signed_ca(rnd, cn))
    return b"".join(certs)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Decide number of certs: 1 to 4
    count = rnd.randint(1, 4)
    der = build_der_bundle(rnd, count)

    # Cap size to 4096 bytes by trimming number of certs if needed
    if len(der) > 4096:
        # reduce to 1 certificate
        der = build_der_bundle(rnd, 1)
        if len(der) > 4096:
            # As a last resort, shrink modulus to 64 bytes and rebuild
            def make_small_cert():
                mod = bytearray(64)
                for i in range(64):
                    mod[i] = rnd.randrange(1, 256)
                mod[0] |= 0x01
                spki = spki_rsa(bytes(mod))
                keyid = bytes(rnd.getrandbits(8) for _ in range(20))
                not_before = (23, 1, 1, 0, 0, 0)
                not_after = (49, 12, 31, 23, 59, 59)
                serial = rnd.randrange(1, 1 << 31)
                tbs = tbs_certificate(serial, not_before, not_after, "Fuzz Small CA", spki, True, keyid)
                sigalg = alg_id_sha256_with_rsa()
                sig = asn1_bit_string(bytes(rnd.getrandbits(8) for _ in range(32)))
                return asn1_seq(tbs + sigalg + sig)
            der = make_small_cert()
    return der

import os
import random
from typing import List

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    # Generate n bytes deterministically using RNG
    return bytes(rng.getrandbits(8) for _ in range(n))

def _make_nonce_set(rng: random.Random) -> bytes:
    # Produce a concatenation of interesting nonce-sized blobs (16-64 bytes each)
    nonces: List[bytes] = []
    # Common sizes
    for sz in (16, 24, 32):
        nonces.append(_rand_bytes(rng, sz))
    # Edge/variant sizes to exercise wc_InitRngNonce paths
    nonces.append(_rand_bytes(rng, 1))     # minimal non-empty
    nonces.append(_rand_bytes(rng, 63))    # near upper bound used by stub (<=64)
    # Pick one extra random size in [2, 64]
    extra_sz = rng.randint(2, 64)
    nonces.append(_rand_bytes(rng, extra_sz))
    return b"".join(nonces)

def _make_seed_buffers(rng: random.Random) -> bytes:
    # Create several seed buffers (wc_GenerateSeed expects sz>0, cap 2048)
    parts: List[bytes] = []
    # A range of sizes, including small and up to the cap
    for sz in (8, 32, 128, 512, 1024, 1800, 2048):
        parts.append(_rand_bytes(rng, sz))
    # Add a random-size block between 1 and 2048
    parts.append(_rand_bytes(rng, rng.randint(1, 2048)))
    return b"".join(parts)

def _make_hash_feed(rng: random.Random) -> bytes:
    # Build a corpus for wc_ShaUpdate / wc_Sha256Update FUZZ_PARAM_STR
    # Include empty segments, small, typical, and 1KB segments (updates are mod-capped in stubs)
    segments: List[bytes] = []
    sizes = [0, 1, 3, 7, 32, 64, 100, 256, 512, 1024]
    for sz in sizes:
        if sz == 0:
            segments.append(b"")
        else:
            segments.append(_rand_bytes(rng, sz))
    # Add a few random-length segments up to 1024
    for _ in range(3):
        segments.append(_rand_bytes(rng, rng.randint(1, 1024)))
    return b"".join(segments)

def _interleave_chunks(chunks: List[bytes], rng: random.Random) -> bytes:
    # Interleave chunks with random small separators to vary FUZZ_PARAM_STR splits
    out = bytearray()
    for i, c in enumerate(chunks):
        out += c
        # Random small spacer (0-8 bytes)
        spacer_len = rng.randint(0, 8)
        if spacer_len:
            out += _rand_bytes(rng, spacer_len)
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build various regions that the fuzz harness will consume via FUZZ_PARAM_STR
    nonces = _make_nonce_set(rng)
    seeds = _make_seed_buffers(rng)
    hash_feed = _make_hash_feed(rng)

    # Also include some additional arbitrary blobs to serve as general buffers
    extras: List[bytes] = []
    for _ in range(4):
        extras.append(_rand_bytes(rng, rng.randint(4, 256)))

    # Interleave to create a single buffer likely to satisfy multiple FUZZ_PARAM_STR calls
    buf = _interleave_chunks([nonces, seeds, hash_feed] + extras, rng)

    # Ensure final size <= 4096
    if len(buf) > 4096:
        buf = buf[:4096]

    # Guarantee non-empty (stubs bail on size==0)
    if not buf:
        buf = _rand_bytes(rng, 32)

    return buf
